INSERT INTO classes (faction_id, name, alias, description, icon) VALUES
-- Империя
(1, 'Sith Warrior', 'Сит-воин', 'На Сита Воина, неудержимого в своей силе, возложена задача уничтожить врагов Империи и обеспечить господство Ситов в галактике. Воин использует разрушительные эмоции страха, гнева и ненависти, чтобы очистить свое тело и разум от слабости, и стать идеальным оружием.', 'images/classes/sith_war.png'),
(1, 'Sith Inquisitor', 'Сит-инквизитор', 'История Империи Ситов полна политических интриг и темных секретов, как и жизнь Сита Инквизитора. Предательство подстерегает за каждым темным уголком Империи, и для выживания нужна врожденная хитрость и умение манипулировать врагами и союзниками. Эксперименты Инквизитора с запрещенными силами проводятся не только для выживания, но и для увеличения собственной власти.', 'images/classes/sith_inq.png'),
(1, 'Imperial Agent', 'Имперский агент', 'Империя владеет множеством звездных систем по всей галактике, но заполучила их не только с помощью Темной стороны Силы. Действуя за кулисами, агенты Имперской Разведки выслеживают и устраняют врагов – начиная с сенаторов Республики и заканчивая вероломными Моффами и кровожадными повстанцами, связанными с Республикой. Агенты Империи должны быть мастерами внедрения, обольщения и скрытного устранения для достижения целей Империи. Они постоянно сталкиваются с противоборством испуганного населения галактики и непостоянством Ситов.', 'images/classes/agent.png'),
(1, 'Bounty Hunter', 'Охотник за головами', 'Множество врагов хотят помешать стремительному росту власти Империи Ситов. Она же, в свою очередь, не скупится на их истреблении, нанимая самых опасных наемников галактики. Получить «черную метку» от Империи – значит провести остаток жизни в страхе, постоянно оглядываясь. Вопрос не в том, найдет ли тебя Охотник за Головами... вопрос – когда.', 'images/classes/bounty_hunter.png'),
-- Республика
(2, 'Jedi Knight', 'Рыцарь-джедай', 'Символ надежды в темное время, Рыцарь хранит наследие Ордена Джедаев – более чем двадцатитысячную историю защиты Республики и сохранения мира по всей галактике. Хотя Рыцари были на протяжении поколений и генералами, и бойцами сопротивления, даже простыми воинами на передовой, их вошедшее в легенды боевое мастерство в эти смутные дни подверглось самому серьезному испытанию.', 'images/classes/jedi_knight.png'),
(2, 'Jedi Consular', 'Джедай-консул', 'Более двадцати тысяч лет Орден Джедаев работал над становлением мира и баланса в Галактической Республике, но с каждым новым днем приходили новые опасности, угрожающие разорвать Орден и Республику на части. Если Республика хочет выжить, ей нужны лидеры и провидцы. Ей нужны Джедаи Консулы.', 'images/classes/jedi_consular.png'),
(2, 'Smuggler', 'Контрабандист', 'Беззаконие стало нормой с тех пор, как началась разрушительная война между Республикой и Империей. Непостоянные политические альянсы и пираты-мародеры сделали самостоятельные путешествия в космосе опасными. Будучи отрезанными от бывших торговых путей, целые звездные системы оказались на грани экономической катастрофы. Находчивые обитатели галактики, которые не боятся нарушить пару законов, могут очень неплохо заработать, доставляя груз в такие горячие точки. Однако для этой задумки нужно иметь отточенные рефлексы, острый ум и умение обращаться с бластером. И даже при этих условиях жизнь Контрабандиста – игра наудачу.', 'images/classes/smuggler.png'),
(2, 'Trooper', 'Солдат', 'Не все герои носят с собой световые мечи. А некоторым достаточно одной смелости в бою. Веками Вооруженные Силы Галактической Республики охраняли ее жителей от, казалось бы, бесконечного натиска Империи Ситов. Республиканские солдаты и по сей день готовы поставить на кон свои жизни.', 'images/classes/trooper.png');